let i = 0

function setup() {
	createCanvas(windowWidth, windowHeight);
}

function draw() {
	background(32)
	noStroke();
	fill(32, 192, 160);
	frameRate(4);
	textSize(max(width, height));
	textAlign(CENTER, CENTER);
	let str = " .+×○♡○×+. #minacoding";
	translate(width * 0.5, height * 0.5);
	// for (let i = 0; i < str.length; i++)
	text(str.charAt(i), 0, 0)
	i = (i + 1) % str.length;
}
